"""Redaktioneller Abgleich mit veröffentlichten Fachgebietsregeln; kein Spielcode."""
from pathlib import Path
import json,sys
R=Path(__file__).resolve().parents[1];p=R/'content/wiki.json';v=json.loads(p.read_bytes());by={a['slug']:a for a in v['articles']}
G=Path(sys.argv[1]);assert not any(slug in by for slug in ['handwerk','kochen','pluendern','waffentechnik','kampf-koerper']), 'Redaktion bereits angewendet'
changed=[]
def s(title,text=None,**kw):return dict(title=title,**({'text':text}if text else{}),**kw)
def table(title,headers,rows,text=None):return s(title,text,table=dict(headers=headers,rows=rows))
def update(slug,summary,sections,quick,related,sources):
 a=by[slug];a.update(summary=summary,sections=sections,quick=quick,related=related,sources=sources,reviewedAt='2026-11-05');changed.append(slug)
def new(slug,title,summary,sections,quick,related,sources):
 a=dict(slug=slug,title=title,navTitle=title,category='Entwicklung',icon='spark');v['articles'].insert(next(i for i,a in enumerate(v['articles'])if a['slug']=='camp'),a);by[slug]=a
 update(slug,summary,sections,quick,related,sources)
skills='[lost_santos]/ls_skills/';inv='[lost_santos]/ls_inventory/'
common=[skills+'server/catalog.lua',skills+'shared/level-effects.lua',skills+'server/progression.lua',skills+'server/background.lua',skills+'server/trees.lua']
update('berufe','Deine Vorgeschichte gibt Startwissen. Was du daraus machst, entscheidest du im Spiel.',[
 s('Welcher Beruf passt zu mir?','Wähle bei der Charaktererstellung eine Vorgeschichte, deren Alltag dich interessiert: Fahrzeuge, Versorgung, Garten, Bau oder Expeditionen. Dein Beruf gibt dir Startlevel und passende Einstiegsausrüstung. Alle 13 Fachgebiete kannst du später lernen; du bist nicht auf eine Klasse festgelegt.'),
 s('So wirkt deine Entscheidung',steps=['Wähle nach deiner Identität den früheren Beruf. Seine fünf Startlevel sind vorgegeben.', 'Verteile drei zusätzliche Startlevel auf reguläre Fähigkeiten. Nahkampf, Schusswaffen und Explosives sind davon ausgenommen.', 'Prüfe Vorschau und Ausrüstung, bevor du bestätigst. Den früheren Beruf wählst du einmal je Charakter.', 'Öffne später L → Fähigkeiten: Die Startlevel geben dir bereits Grundwissen und freie Talentpunkte. Welche Fachrichtung du zuerst lernst, wählst du selbst.']),
 table('Die Berufe im Vergleich',['Beruf','Fünf feste Startlevel','Passt zu dir, wenn du …'],[
 ['Mechaniker','Mechanik 3 · Handwerk 1 · Plündern 1','Fahrzeuge erhalten, erforschen und ausbauen möchtest.'],
 ['Arzt','Medizin 3 · Plündern 1 · Kochen 1','Verletzungen beurteilen und andere versorgen möchtest.'],
 ['Polizist','Plündern 1 · Körper 1 · Schusswaffen 2 · Nahkampf 1','erkunden, bergen und mit Schusswaffen kämpfen möchtest.'],
 ['Soldat','Überleben 1 · Körper 1 · Schusswaffen 2 · Explosives 1','Expeditionen und den Kampf gegen Zombies verbinden möchtest.'],
 ['Bauarbeiter','Bauen 2 · Handwerk 1 · Körper 1 · Nahkampf 1','ein Camp aufbauen und Materialien verarbeiten möchtest.'],
 ['Feuerwehrmann','Körper 2 · Medizin 1 · Plündern 1 · Nahkampf 1','körperliche Einsätze und Hilfe für andere verbinden möchtest.'],
 ['Koch','Kochen 3 · Handwerk 1 · Nahkampf 1','die Gruppe mit Mahlzeiten und Reisevorräten versorgen möchtest.'],
 ['Jäger','Überleben 2 · Plündern 1 · Körper 1 · Schusswaffen 1','Tieren nachspüren und draußen Vorräte gewinnen möchtest.'],
 ['Gärtner','Farming 3 · Überleben 1 · Kochen 1','Pflanzen ziehen und eine Versorgung im Camp aufbauen möchtest.'],
 ['Waffentechniker','Waffentechnik 3 · Handwerk 1 · Schusswaffen 1','an Waffen, Zubehör und Forschungsprojekten arbeiten möchtest.'],
 ['Sicherheitsdienst','Plündern 2 · Körper 1 · Nahkampf 1 · Schusswaffen 1','Bergung und bewaffnete Ausflüge verbinden möchtest.'],
 ['Forstarbeiter','Überleben 2 · Körper 1 · Handwerk 1 · Nahkampf 1','Rohstoffe gewinnen und Feldausrüstung erhalten möchtest.'],
 ['Arbeitsloser','Fünf Berufspunkte frei verteilen','deine Vorgeschichte selbst zusammenstellen möchtest.']]),
 s('Volle Praxis in deinen Berufsfächern','Die ursprünglichen fünf Berufslevel bestimmen deine vertrauten Fächer. Dort erhältst du die volle Praxis-XP, in allen anderen die Hälfte. Die drei zusätzlichen Startlevel ändern diese Zuordnung nicht. Beispiel: Ein Mechaniker lernt Mechanik, Handwerk und Plündern mit voller Praxis. Zusätzliche Farming-Startlevel erleichtern den Einstieg, machen Farming aber nicht zu einem seiner Berufsfächer.'),
 s('Wenn du Arbeitsloser wählst','Verteile fünf Berufspunkte selbst: höchstens zwei je regulärer Fähigkeit und insgesamt höchstens einen Kampfpunkt. Die so gewählten Berufsfächer erhalten volle Praxis-XP. Dazu kommen wie bei allen anderen drei freie reguläre Startlevel.'),
 s('Was du für deinen Wunschweg zusätzlich brauchst','Startwissen ersetzt keinen Arbeitsplatz. Ein Waffentechniker braucht später eine gebaute Waffenwerkbank; ein Mechaniker Modellwissen und Werkstatt. Koch und Gärtner bauen Versorgung über Küche, Beete und gewählte Verfahren aus. Die Fachanleitungen unten helfen beim nächsten konkreten Schritt. Die Berufsvorschau zeigt deine tatsächlich verfügbare Einstiegsausrüstung.')],
 ['5 Berufslevel + 3 freie reguläre Level','Berufsfächer: volle Praxis-XP','Alle Fachgebiete bleiben erlernbar'],
 ['faehigkeiten','mechanik','medizin','farming','kochen','handwerk','waffentechnik'],common+[inv+'shared/professions.lua'])

update('faehigkeiten','Erfahrung macht dich sicherer. Talentpunkte bestimmen deine Fachrichtung.',[
 s('Dein nächster sinnvoller Schritt','Öffne L → Fähigkeiten und wähle das Fach, das du gerade benutzt. Die Seite zeigt dein Grundwissen, den nächsten Levelschritt und fünf bebilderte Fachrichtungen. Überlege dir eine konkrete Aufgabe, etwa Setzlinge anziehen oder eine Waffe reparieren. Wähle dann die dafür nötigen Talente und beschaffe den passenden Arbeitsplatz.'),
 table('Drei Dinge, die zusammengehören',['Fortschritt','Was er für dich tut','Beispiel'],[
 ['Fachlevel','Wächst durch passende Praxis; verbessert Routine und erschließt Grundwissen.','Farming 5: Tomaten anbauen und bis zu zwei Anzuchten betreuen.'],
 ['Talentpunkt','Ein Punkt je Fachlevel; du lernst die Spezialisierungen dieses Fachs selbst.','„Setzlinge anziehen“ eröffnet das Anzuchtverfahren.'],
 ['Arbeitsplatz und Ausrüstung','Bleiben zusätzlich erforderlich; eine Freischaltung baut sie nicht für dich.','Eine Anzucht braucht Saat, Wasser und einen freien Pflanzplatz.']]),
 table('Welches Fach hilft mir weiter?',['Fach','Was mit Erfahrung besser wird','Wofür du Talente wählst'],[
 ['Mechanik','Diagnose, parallele Forschung und Routine bei Fahrzeugarbeiten.','Fahrzeugklassen reparieren, restaurieren und bauen; Leistungs-Upgrades.'],
 ['Medizin','Diagnose, Behandlungstempo und Heilwirkung.','Erstversorgung, Trauma, Infektionen, Notfälle und Meisterschaft.'],
 ['Handwerk','Material- und Reparaturbefund, Ertragsvergleich und parallele Werkstücke.','Holz, Textil/Leder, Metall, Rückgewinnung und Werkzeugpflege.'],
 ['Bauen','Mehr Campblöcke und schnellere Aufbauarbeit.','Formen, Vorfertigung, Befestigungen, Elektrik und Bauabschnitte.'],
 ['Kochen','Zutatenwissen, Portions- und Frischevergleich, parallele Vorratsaufträge.','Feldküche, Lagergerichte, Backen, Haltbarmachen und Zutatenverwertung.'],
 ['Farming','Neue Sorten, mehr Anzuchtplätze und Bedarfseinschätzung.','Anzucht, Pflege, Pflanzenzucht, Bodenwirtschaft und Gartenbetrieb.'],
 ['Überleben','Spurenwissen, Materialkunde und schonendere Rohstoffarbeit.','Gezielte Entnahme, Sammeln, Tierverwertung, Fährten und Feldausrüstung.'],
 ['Plündern','Eigene Fundnotizen, Routen, Werkzeugbefunde und schnellere Suche.','Befunde, Suchverfahren, Schlösser, Bergung und Ordnung.'],
 ['Waffentechnik','Reparatur- und Kompatibilitätsbefund, mehr Untersuchungen und Arbeitsroutine.','Instandsetzung, Zubehör, Munition, Verwertung und Planwissen.'],
 ['Körper','Nahrung und Wasser reichen mit wachsender Routine länger.','Ausdauer, Versorgung, Widerstand, Stürze und Abwehrkräfte.'],
 ['Nahkampf','Nahkampfwaffen verschleißen bei Zombietreffern langsamer.','Kampfstil, Ausdauer, Kontrolle, Pflege und Beute.'],
 ['Schusswaffen','Weniger Rückstoß, kürzeres Nachladen und geringerer Verschleiß.','Handhabung, Kontrolle, Zombiejagd, Pflege und Munitionsroutine.'],
 ['Explosives','Bessere Werferhandhabung und schnellere Sprengmittelherstellung.','Spreng- und Werferverfahren mit ihren jeweiligen Voraussetzungen.']]),
 s('Ein Talent lernen',steps=['Einmal anklicken: Wirkung, Vorgänger und Voraussetzungen lesen.', 'Zum Lernen doppelklicken oder den Lernknopf wählen.', 'Die Ausgabe ausdrücklich bestätigen. Jeder wählbare Knoten kostet einen Punkt dieses Fachs.', 'Du brauchst die verbundenen Vorgänger. Die Reihenfolge zwischen den Fachrichtungen bestimmst du selbst; ein Levelaufstieg lernt keinen Knoten automatisch.']),
 s('So sammelst du Erfahrung','Praxis entsteht durch passende erfolgreiche Tätigkeiten: etwa private Ernten, verbessernde Reparaturen, Behandlung, Herstellung, bezahlten Aufbau oder geeignete Sammelaktionen. Ein Menü immer wieder zu öffnen zählt nicht. Deine Berufsfächer erhalten volle, andere halbe Praxis-XP. Jeder Fachbereich reicht bis Level 15 und bietet 15 lernbare Talente.'),
 s('Nach der Talent-Neuordnung','Wenn dir das Logbuch eine Rücksetzung deiner Talentwahl meldet, sind die Punkte wieder frei. Deine Level, XP, Beruf und bereits erworbenes Modell- oder Planwissen bleiben erhalten. Öffne die Fähigkeiten, verteile neu und bestätige den Hinweis anschließend mit „Verstanden“. Das ist keine jederzeit verfügbare kostenlose Neuverteilung.')],
 ['Levelwissen kommt automatisch','Talente wählst und bestätigst du selbst','Arbeitsplätze bleiben Voraussetzung'],
 ['berufe','farming','kochen','handwerk','mechanik','medizin','waffentechnik','pluendern','ueberlebensbaum','kampf-koerper'],common+[skills+'server/exports.lua',skills+'server/talent-reset.lua',skills+'server/farming.lua',skills+'server/cooking.lua',skills+'server/survival.lua',skills+'server/looting.lua',skills+'server/weapon-tech.lua',skills+'server/field-trees.lua',skills+'server/medicine-tree.lua',skills+'server/mechanic-tree.lua',skills+'server/body-tree.lua',skills+'server/combat-trees.lua'])

new('handwerk','Handwerk & Werkzeugpflege','Werkstoffe aufbereiten, Ausrüstung fertigen und gebrauchte Werkzeuge erhalten.',[
 s('Deine erste Werkbank','Grundrezepte stehen dir von Anfang an offen. Für Facharbeiten brauchst du das passende Talent und ein fertiges Handwerksmodul. Öffne dort die Werkstatt, wähle einen bekannten Auftrag und prüfe Materialien, Werkzeuge, Arbeitsplatzstufe und Platz für das Ergebnis.'),
 s('Ein greifbarer Einstieg','Wenn deine Werkzeuge knapp werden, beginne mit „Notbehelf“. Damit reparierst du geeignete Hammer, Rohrzangen, Schaufeln, Spitzhacken und Angelruten gegen Material bis 60 %. Mit „Werkzeugpflege“ und „Ausrüster“ folgen 80 % beziehungsweise 100 %; dafür brauchst du Handwerk II beziehungsweise III.'),
 table('Was du mit den Leveln lernst',['Level','Automatisches Grundwissen'],[['3','Verwendungen mitgeführter Werkstoffe in deinen bekannten Aufträgen erkennen.'],['6','Bekannte Reparaturwege und vollständigen Materialbedarf vergleichen.'],['10','Feste Erträge bekannter Zerlegeverfahren vorab vergleichen.'],['12 / 15','Bis zu zwei / drei bezahlte trocknende oder abbindende Werkstücke betreuen. Arbeitsplatzkapazität bleibt nötig.']], 'Jedes Level verkürzt außerdem passende Handwerksarbeiten und Kleidungspflege.'),
 table('Deine fünf Fachrichtungen',['Richtung','Was daraus wird'],[['Holzverarbeitung','Holzverbinder, Bauholz und ein bezahlter Bausatz für eine gemeinsame Holzkiste.'],['Textil & Leder','Seile, Lederpolster und größere selbst gefertigte Rucksäcke.'],['Metall & Verbindungen','Befestigungen und verstärktes Reparaturmaterial.'],['Zerlegen & Improvisieren','Geeignete Werkzeuge oder leere Rucksäcke verwerten, sorgfältiger zurückgewinnen und alternative Werkstoffe nutzen.'],['Reparatur & Routine','Werkzeuge stufenweise besser erhalten und Handwerksarbeiten beschleunigen.']]),
 s('Werkstücke brauchen Zeit und Material','Holz- und Leimaufträge können trocknen oder abbinden, während du anderes erledigst. Die Zutaten bezahlst du beim Start; zum Abholen brauchst du Platz und Zugang zur Werkstatt. Werkzeugreparaturen bleiben persönliche Arbeit. Zerlegen verbraucht das Original endgültig – vergleiche vorher Reparatur und Ertrag.')],
 ['Grundrezepte bleiben frei','Werkzeugreparatur: 60 / 80 / 100 %','Mehr Fachwissen durch echte Arbeit'],['faehigkeiten','crafting','camp','waffentechnik'],common+[skills+'server/field-trees.lua',inv+'shared/handwork.lua',inv+'server/cooking.lua'])

new('kochen','Kochen & Reisevorräte','Vom ersten warmen Essen bis zur Versorgung für die nächste Expedition.',[
 s('Mit der Grundversorgung anfangen','Einfache Gerichte und Wasseraufbereitung bleiben ohne Talent verfügbar. Nutze eine vorhandene Campküche und prüfe Rezept, frische Zutaten, Werkzeug und benötigte Ausbaustufe. Ein höheres Kochlevel hilft bei Tempo und Nährwert; neue Verfahren wählst du mit Talentpunkten.'),
 s('Welcher Weg passt zu dir?','Für Ausflüge bietet die Feldküche tragbare Gerichte und Rationen. Für eine Gruppe sind Lagergerichte und mehrere bezahlte Kochdurchgänge interessant. Möchtest du Vorräte für später, beginne mit Trocknen und baue anschließend Einkochen aus.'),
 table('Was du mit den Leveln lernst',['Level','Automatisches Grundwissen'],[['2','Zutaten ihren bekannten Rezepten zuordnen.'],['5','Zutaten, Nahrung und Wasser je Portion vergleichen.'],['8','Die kürzeste verbleibende Frische einer geplanten Zutatencharge beurteilen.'],['10','Besondere Verwendungen von Fett, Fisch und Mehl erkennen.'],['12 / 15','Bis zu zwei / drei bezahlte Vorratsaufträge betreuen, mit passendem Talent und freier Küchenkapazität.']]),
 table('Deine fünf Fachrichtungen',['Richtung','Was daraus wird'],[['Feldküche','Reise-Pfanne, gepackte Tourenration und Suppen am tragbaren Feldkocher.'],['Lagerküche','Kräftigere Gerichte, Campmenüs und bis zu vier bezahlte Durchgänge eines bekannten Lagergerichts.'],['Backstube','Kartoffelfladen, Maisbrot und getrockneter Zwieback.'],['Haltbarmachen','Fleisch oder Fisch trocknen, Gemüse einkochen und Langzeitproviant herstellen.'],['Zutatenwirtschaft','Freigegebene Fischvarianten, frische Küchenreste und vorhandenen frischen Proviant weiterverarbeiten.']]),
 s('Haltbar heißt nicht unvergänglich','Eine Küche ersetzt weder Zutaten noch geeignete Gefäße oder Brennstoff. Große Gerichte und Einkochen bleiben an passende Campküchen gebunden. Verpacken macht alte Zutaten nicht wieder frisch; bei Tourenrationen und umgearbeitetem Proviant begrenzt die ursprüngliche Haltbarkeit das Ergebnis. Verdorbenes und organischer Abfall sind keine Kochzutaten.')],
 ['Level: Wissen, Tempo und Nährwert','Talente: neue Kochverfahren','Frische und Arbeitsplatz zählen weiter'],['faehigkeiten','crafting','farming','camp-lager'],common+[skills+'server/cooking.lua',inv+'shared/kitchen-orders.lua',inv+'server/cooking.lua',inv+'server/cooking.lua'])

new('pluendern','Plündern & Bergung','Fundstellen einschätzen, Beute sorgfältig lösen und eigene Routen aufbauen.',[
 s('Suchen kannst du von Anfang an','Untersuche eine erreichbare Fundstelle über Alt. Ihr Inhalt wird beim erneuten Öffnen nicht neu gewürfelt. Erfahrung macht die gewöhnliche Suche schneller; neue Such- und Bergungsverfahren lernst du selbst. Befunde zeigen dir keine ungeöffneten Inhalte.'),
 s('Entscheide vor der Bergung','Manche geeigneten Funde sitzen fest oder sind verschüttet. Mit dem richtigen Talent und Werkzeug löst du sie sorgfältig. Schnellbergung spart Zeit, kostet bei solchen Funden aber Zustand und macht mehr Lärm. Es bleibt dasselbe Exemplar – du erzeugst keinen zweiten Fund.'),
 table('Was du mit den Leveln lernst',['Level','Automatisches Grundwissen'],[['3','Eigene Notiz zu einem selbst besuchten Fundplatz anlegen.'],['6','Tatsächlichen Verschluss und benötigte Werkzeuge einer untersuchten Stelle einschätzen.'],['10','Bis zu sechs eigene Fundnotizen zu einer Route ordnen.'],['12','Mitgeführte Vorräte mit deiner eigenen Bedarfsliste vergleichen.'],['15','Bis zu zwölf bekannte Stellen nach offener Bergung und Werkzeugbedarf zusammenstellen.']]),
 table('Deine fünf Fachrichtungen',['Richtung','Wobei sie hilft'],[['Fundstellenkunde','Behälterbauart, Werkzeugbedarf und selbst erkundete Bereiche auswerten.'],['Suchverfahren','Vorsichtiger suchen, freigelegte Funde rasch lösen oder verschüttete Stellen gründlich freilegen.'],['Schlösser','Das Öffnungs-Minispiel geeigneter Eventkisten erleichtern.'],['Sorgfältige Bergung','Festliegende Werkzeuge, Waffen und empfindliche Ausrüstung kontrolliert übernehmen.'],['Transport & Ordnung','Geeignete normale 20er-Stapel auf 25, 30 oder 40 erhöhen. Das Gewicht bleibt erhalten.']]),
 s('Kein Fundglück-Schalter','Die alte Fundglück-Spezialisierung ist durch konkrete Fundstellenkunde ersetzt. Deine Kenntnisse würfeln keine unbekannten Inhalte neu und machen keinen Fundort zur Garantie für Militärbeute. Notizen zeigen deinen letzten eigenen Befund; andere Spieler können die gemeinsame Stelle inzwischen verändert haben.')],
 ['Notizen nur zu selbst besuchten Stellen','Sorgfältig bergen oder rascher mit Nachteilen','Größere Stapel behalten ihr Gewicht'],['faehigkeiten','looten','inventar','ueberlebensbaum'],common+[skills+'server/looting.lua',inv+'server/looting.lua',inv+'shared/looting-work.lua'])

new('waffentechnik','Waffentechnik & Waffenwerkbank','Waffen erhalten, passende Teile fertigen und echte Prüfstücke untersuchen.',[
 s('Zuerst die Waffenwerkbank','Normale Waffenhandhabung und Magazine bleiben von Anfang an nutzbar. Für Waffentechnik brauchst du später eine tatsächlich gebaute Waffenwerkbank im Handwerksmodul III. Eine gewöhnliche Werkbank oder ein gelerntes Talent allein reichen nicht. Fortgeschrittene Verfahren brauchen außerdem Strom.'),
 s('Beginne mit einem konkreten Vorhaben','Für eine beschädigte reparierbare Waffe wähle Instandsetzung. Für Zubehör prüfe zuerst die Kompatibilität deines Modells. Reparatur und Verwertung verlangen ein abgelegtes, entladenes geeignetes Exemplar und die angezeigten Werkstoffe. Kontrolliere vor jeder Bestätigung, ob das Original zurückkehrt oder verbraucht wird.'),
 table('Was du mit den Leveln lernst',['Level','Automatisches Grundwissen'],[['3','Defektarten und bekannte Reparaturwege unterscheiden.'],['5','Bis zu zwei getrennte Untersuchungen betreuen.'],['8','Verschleißbedingte Störungen und nächste Instandsetzung beurteilen.'],['10','Bekannte Teile und Baugruppen mit der tatsächlichen Waffenfamilie vergleichen.'],['12','Reparierbarkeit und Werkstoffe bekannter Baugruppen beurteilen.'],['15','Bis zu drei getrennte Untersuchungen betreuen. Werkbankplätze und Prüfstücke bleiben erforderlich.']], 'Mit Erfahrung werden außerdem Waffenbaurezepte und Magazinhandgriffe zügiger.'),
 table('Deine fünf Fachrichtungen',['Richtung','Was daraus wird'],[['Büchsenmacher','Geeignete Waffen bis 60 %, später mit Strom bis 80 % beziehungsweise 100 % instand setzen.'],['Teilefertigung','Passendes Zubehör, leere erweiterte Magazine und fortgeschrittene Präzisionsteile fertigen.'],['Munitionsfertigung','Die freigegebenen Kurz-, Langwaffen- und Spezialmunitionstypen aus vollständigen Zutaten herstellen.'],['Waffenverwertung','Entladene Waffen oder geeignetes loses Zubehör zerlegen und später modellgebundene Baugruppen bergen.'],['Planwissen & Erprobung','Gefundene Präzisionspläne untersuchen, Waffenfamilien erproben und passende Baugruppen instand setzen oder einsetzen.']]),
 s('Forschung ist Arbeit mit echten Gegenständen','Nach erlerntem Planwissen hast du zunächst einen Forschungsplatz. Einen gefundenen Präzisionsplan untersuchst du an der Waffenwerkbank. Für eine Familienuntersuchung spannst du eine geeignete entladene Waffe ohne Zubehör 15 Minuten ein; du erhältst danach dasselbe Prüfstück zurück. Strom ist beim Start und beim Abholen nötig. Die verstrichene Prüfzeit ersetzt diese Voraussetzungen nicht.'),
 s('Baugruppen passen zu einem bestimmten Modell','Baugruppenbergung verbraucht die ursprüngliche Waffe und erzeugt keine Munition. Die geborgene Baugruppe gehört exakt zu ihrem Modell und hat höchstens 40 % Zustand. Mit passender Forschung, Talent, Material und Strom kannst du sie bis 80 % instand setzen und in eine reparierbare modellgleiche Waffe bis 80 % einsetzen. Das ist keine Wiederbelebung dauerhaft defekter Waffen.')],
 ['Gebaute Waffenwerkbank an Handwerk III','Fortgeschrittene Arbeit benötigt Strom','Modell, Zustand und Material prüfen'],['faehigkeiten','handwerk','camp','stromnetz','inventar'],common+[skills+'server/weapon-tech.lua',inv+'shared/weapon-studies.lua',inv+'server/weapon-studies.lua'])

new('kampf-koerper','Körper & Kampfpraxis','Länger durchhalten und im Kampf mit Zombies sicherer werden.',[
 s('Vier Fächer, vier Lernwege','Körper wächst durch geeignete Bewegung zu Fuß. Nahkampf, Schusswaffen und Explosives entwickeln sich über die jeweils zugeordneten Zombie-Kills. Waffen bleiben auch auf Level 0 benutzbar. In L → Fähigkeiten wählst du für jedes Fach eigene Talente; ein Punkt aus Körper lässt sich nicht im Schusswaffenbaum ausgeben.'),
 s('Was die Level ohne Talentkauf verbessern','Körper senkt schrittweise Nahrung- und Wasserverbrauch. Nahkampf schont deine Waffen bei Zombietreffern. Schusswaffen verbessert Rückstoß, Nachladezeit und Verschleiß. Explosives verbessert Werferhandhabung und die Zeit passender Herstellungsrezepte. Die bebilderten Bäume ergänzen diese Routine um von dir gewählte Wirkungen.'),
 table('Worauf du dich spezialisieren kannst',['Fach','Beispiele aus seinen Talenten'],[['Körper','Längere Ausdauer, sparsamere Versorgung, geringerer Zombieschaden, bessere Sturzfolgen und langsamere Infektionsausbreitung.'],['Nahkampf','Kampftempo, Ausdauer, Beweglichkeit, Waffenpflege und besondere Wirkungen nach Zombie-Kills.'],['Schusswaffen','Schnelleres Nachladen, Rückstoßkontrolle, Waffenpflege, weniger Ladehemmungen und Zombiejagd.'],['Explosives','Sprengwirkung, Werferhandhabung, Pflege und besondere Wirkungen nach geeigneten Kills.']]),
 s('Eine Chance ist keine Garantie','Einige gelernte Talente lösen nur gelegentlich aus. Wo ihre Chance mit weiterer Erfahrung wächst, zeigt dir der Knoten den tatsächlichen Wert. Ein in der Beschreibung genanntes Wachstumslevel ist keine zusätzliche Kaufsperre: Freie Punkte und verbundene Vorgänger entscheiden über das Lernen.'),
 s('Die Grenzen bleiben wichtig','Kampfschadensboni gelten gegen Zombies, nicht gegen andere Spieler. Widerstand und Abwehrkräfte machen dich nicht unverwundbar und behandeln keine vorhandene Infektion. Waffen nutzen sich weiter ab. Bewegung im Fahrzeug, Teleports oder Admin-Dienst zählen nicht als Körpertraining.')],
 ['Waffen bleiben ab Level 0 benutzbar','Jedes Fach hat eigene Talentpunkte','Kampfschadensboni gelten gegen Zombies'],['faehigkeiten','medizin','inventar','zombies'],common+[skills+'server/body-tree.lua',skills+'server/combat-trees.lua',inv+'server/body.lua',inv+'server/combat.lua'])

