a=by['farming'];a['sections'][2]=table('Diese Sorten lernst du automatisch',['Farming-Level','Anbauwissen'],[['0','Karotten'],['2','Kartoffeln'],['5','Tomaten'],['8','Weizen'],['10','Mais']], 'Für neue Sorten brauchst du keine Talentpunkte. Saatgut und ein geeigneter freier Pflanzplatz bleiben erforderlich. Vorhandene Pflanzen kannst du auch ohne eigenes Sortenwissen versorgen und ernten.')
a['sections'][3]=s('Wachstum und Pflege','Drei gewässerte Wachstumsschritte führen zur Reife. Ohne Wasser wartet die Pflanze. Dünger und dein Farminglevel können die gepflegten Wachstumsstufen verkürzen; eine Wasserreserve ersetzt keinen unbegrenzten Vorrat. Die Pflanzenansicht zeigt den aktuellen Zustand und was als Nächstes fehlt.')
a['sections'][6]=table('Fünf Fachrichtungen für deinen Garten',['Richtung','Deine Möglichkeiten'],[['Anzucht','Saat aufbereiten, sortenfeste Setzlinge anziehen und mehrere Anzuchten vorbereiten.'],['Gartenpflege','Wasser für den nächsten Schritt hinterlegen, Pflegerunden und endliche Bewässerung nutzen.'],['Pflanzenzucht','Junge Pflanzen bergen und umsetzen; reife Pflanzen gezielt für Saat statt Nahrung ernten.'],['Bodenwirtschaft','Organische Reste kompostieren, größere Düngeraufträge und Fruchtfolge nutzen.'],['Gartenbetrieb','Anbaufolgen vormerken sowie bis zu vier passende Nachbarplätze nacheinander bepflanzen oder ernten.']])
a['sections'].insert(3,table('Anzuchtplätze und Erfahrung',['Level','Persönliche Anzuchtkapazität'],[['0','Ein Platz, sobald das passende Anzuchttalent gelernt ist.'],['5','Zwei gleichzeitige Anzuchten.'],['10','Drei gleichzeitige Anzuchten.'],['12','Saat-, Wasser- und Düngerbedarf bekannter Anbaufolgen vergleichen.'],['15','Vier gleichzeitige Anzuchten.']], 'Das ist keine zusätzliche Beetgröße: Jede Anzucht belegt einen tatsächlich freien Pflanzplatz und verbraucht Saat sowie Wasser.'))
a['quick']=['Neue Sorten durch Farming-Level','Talente eröffnen Anbauverfahren','Freie Plätze, Wasser und Saat erforderlich'];a['sources']=[skills+'server/farming.lua',skills+'shared/level-effects.lua',inv+'shared/farming.lua',inv+'server/farming.lua',inv+'shared/farm-work.lua',inv+'server/farming.lua'];a['related']=['faehigkeiten','kochen','camp','naturressourcen'];a['reviewedAt']='2026-11-05';changed.append('farming')

update('ueberlebensbaum','Draußen gezielter arbeiten, Spuren lesen und Feldausrüstung erhalten.',[
 s('Erfahrung aus dem Alltag','Sammeln, Angeln und Rohstoffarbeit bleiben ohne Talent möglich. Geeignete Naturgewinnung und Tierverwertung bringen Praxis; Erfahrung verkürzt passende Arbeiten und schont dabei Werkzeuge. Neue Arbeitsweisen wählst du im Überlebensbaum.'),
 s('Mit Spurenlesen anfangen','Ab Überleben 3 erkennst du über /spuren nahe junge Landtierspuren. Sie stammen aus vergangenen Bewegungen. Tierart, damalige Richtung und ungefähres Alter erschließen sich mit weiteren Leveln. Eine Spur garantiert kein noch anwesendes Tier.'),
 table('Was du mit den Leveln lernst',['Level','Automatisches Grundwissen'],[['3','Nahe junge Landtierspuren entdecken.'],['6','Naturmaterialien bekannten Feldrezepten zuordnen.'],['9','Tierart und damalige Laufrichtung lesen.'],['12','Ungefähres Spurenalter einschätzen.'],['15','Aus selbst gelesenen Hinweisen einen Revierbefund erstellen.']]),
 table('Deine fünf Fachrichtungen',['Richtung','Was du bewusst auswählst'],[['Rohstoffarbeit','Kleinere Teilentnahmen, vorhandene Materialanteile und einfache Feldaufbereitung.'],['Sammelkunde','Nahrung oder Saat, geeignete Pflanzenfasern und eine örtliche Sammelrunde.'],['Jagdverwertung','Fell schonen, vorhandenes Fett aufbereiten und tierische Werkstoffe nutzen.'],['Fährtenkunde','Größeren Suchkreis, zusammenhängenden Verlauf und ältere vorhandene Spuren auswerten.'],['Feldausrüstung','Ressourcenwerkzeuge unterwegs bis 30 % beziehungsweise 50 % erhalten oder ihren Werkzeugkopf retten.']]),
 s('Wissen schafft keine neuen Vorräte','Entnahmen und Verwertung nutzen den tatsächlichen verbleibenden Bestand. Wer Fell priorisiert, entscheidet sich gegen eine zusätzliche Fleischportion. Werkzeugreparaturen kosten Material; Ausschlachten verbraucht das Original. Sammelrunden finden vor Ort statt, und Fährten bleiben historische Hinweise.')],
 ['Spuren ab Überleben 3','Talente eröffnen gezielte Verfahren','Gemeinsame Vorräte bleiben endlich'],['naturressourcen','jagd','angeln','faehigkeiten'],common+[skills+'server/survival.lua',inv+'server/nature.lua',inv+'server/survival.lua','[lost_santos]/ls_hunting/server/main.lua'])

a=by['mechanik'];a['sections'].insert(2,table('Was dein Mechaniklevel erschließt',['Level','Grundwissen und Ausbau'],[['4','Zustandsbereiche statt nur grober Einschätzung.'],['5','Zwei parallele Forschungen; Ausbauanforderung für Mechanikmodul II erfüllt.'],['7','Genaue Diagnosewerte.'],['10','Drei parallele Forschungen; Ausbauanforderung für Mechanikmodul III erfüllt.'],['15','Vier parallele Forschungen.']], 'Erfahrung verkürzt außerdem Fahrzeugarbeiten. Ein erreichtes Level baut kein Modul automatisch; Talent, Modellwissen und tatsächliche Werkstatt bleiben getrennte Voraussetzungen.'))
a['sources']+=[skills+'shared/level-effects.lua',skills+'server/mechanic-tree.lua',inv+'shared/vehicle-research.lua',inv+'server/model-research.lua'];a['reviewedAt']='2026-11-05';changed.append('mechanik')

a=by['medizin'];a['sections'].insert(2,table('Was dein Medizinlevel erschließt',['Level','Genauere Befunde'],[['2','Bei anderen Blutungsstufen, Brüche und Gewebeschaden erkennen.'],['3','Den eigenen genauen Infektionswert an einer Krankenstation oder mit Feldchirurg erkennen.'],['5','Bei anderen Blutmenge und verschmutzte Wunden erkennen.'],['8','Bei anderen den genauen Infektionswert an einer Krankenstation oder mit Feldchirurg erkennen; Labordiagnostik kann das früher ermöglichen.']], 'Unterwegs ohne passende Ausstattung bleibt die Infektionsanzeige grob. Erfahrung verbessert außerdem Behandlungstempo und Heilwirkung.'))
a['sections'].insert(3,s('Talente und Krankenstation ergänzen sich','Die fünf Richtungen sind Erstversorgung, Trauma, Infektiologie, Notfälle und Meisterschaft. Du bestimmst, welche Verfahren du zuerst lernst. Eine tatsächlich vorhandene Krankenstation erleichtert die Versorgung; Stufe II lässt beim Schienen Brüche sofort heilen, Stufe III ermöglicht Komplettversorgung. Das sind Wirkungen des Arbeitsplatzes, keine automatisch gebauten Levelbelohnungen.'))
a['sources']+=[skills+'server/medicine-tree.lua',skills+'shared/level-effects.lua'];a['reviewedAt']='2026-11-05';changed.append('medizin')

a=by['camp'];a['sections'].append(table('Bauen lernen und spezialisieren',['Talentweg','Deine Möglichkeiten'],[['Tragwerk & Formen', 'Weitere Holzformen, Etagen, Treppen und Dachfamilien.'], ['Gebäudeausbau', 'Wand-, Trag- und Dachbausätze vorfertigen.'], ['Befestigungen', 'Holz, Stein und Metallbefestigungen ausbauen.'], ['Elektrik', 'Generatoren, Arbeitslampen, Solar und Stromspeicher herstellen.'], ['Baueffizienz', 'Eigene neue Pläne gruppieren, Bausätze bündeln und Bauabschnitte erneut planen.']], 'Bezahlter abgeschlossener Aufbau und Ausbau bringen Baupraxis; Versetzen und Rückbauen nicht. Erfahrung verkürzt die Aufbauzeit. Deine fünf Talentwege erschließen Holzformen und Etagen, Vorfertigung, Befestigungen, Generator/Solar/Speicher sowie geplante Baugruppen. Gelernte Vorfertigung ersetzt weder Materialkosten noch das Formtalent beim Aufstellen. Mit passenden Planungstalenten kannst du eigene neue Baupläne gruppieren und Abschnitte erneut als unbezahlte Pläne platzieren.'))
a['sources']+=[skills+'server/exports.lua',skills+'server/field-trees.lua',skills+'shared/level-effects.lua'];a['reviewedAt']='2026-11-05';changed.append('camp')

a=by['crafting'];a['summary']='Der praktische Einstieg; eigene Anleitungen vertiefen Handwerk und Kochen.'
a['sections'][2]=s('Kochen und Vorräte haltbar machen','Kochlevel verbessern automatisch Zutatenwissen, Tempo, Nährwert und später parallele Vorratsaufträge. Talente eröffnen Feldküche, Lagergerichte, Backen, Haltbarmachen und Zutatenverwertung. Welche Zutaten und Küchenstufe nötig sind, steht am Auftrag. Die eigene Kochanleitung hilft dir bei der Wahl des ersten Wegs.')
a['sections'][5]=s('Handwerk im Alltag','Handwerkslevel erschließen Materialbefunde, Reparaturvergleiche und mehr parallele Werkstücke. Die fünf Talentwege führen durch Holz, Textilien/Leder, Metall, Zerlegen und Werkzeugpflege. Für eine Reparatur brauchst du das passende Verfahren, Material und eine fertige Werkstatt. Die eigene Handwerksanleitung erklärt den Einstieg.')
a['related']=['handwerk','kochen','camp','jagd','inventar'];a['sources']+=[skills+'server/cooking.lua',skills+'server/field-trees.lua'];a['reviewedAt']='2026-11-05';changed.append('crafting')

a=by['looten'];a['sections'][5]=s('Fundstellenkunde statt neuer Würfe','Der Plündernbaum hilft dir, Behälter und Werkzeugbedarf einzuschätzen, sorgfältig zu bergen und eigene Fundnotizen auszuwerten. Die frühere Fundglück-Spezialisierung ist ersetzt. Fachwissen würfelt keinen geöffneten Behälter neu und garantiert keine höherwertige Beute. Zustand, Schutz, Stauraum und Gewicht bleiben entscheidend.');a['related']=list(dict.fromkeys(a['related']+['pluendern']));a['sources']+=[skills+'server/looting.lua'];a['reviewedAt']='2026-11-05';changed.append('looten')
a=by['erste-schritte'];a['sections'][1]['steps'][2]='Mit L erreichst du Übersicht, Aufträge, Fähigkeiten und Archiv im Logbuch. Wähle dort einen nächsten Schritt statt alles auf einmal zu lesen.';a['reviewedAt']='2026-11-05';changed.append('erste-schritte')

